// ============================================================
//  Empfehlungsdienst
//  Eingänge (alle per Wildcard abonniert):
//    .../profiles/+/+       Streckenprofile (retained)
//    .../routes/+/+         Routen (nur für Abfahrtszeit und Wochentage)
//    .../live/bicimad/+     Räder/Plätze je Station
//    .../live/weather       aktuelles Wetter
//    .../system/+           Status der Collectors (Birth / Close / Last Will)
//    Takt alle 60 s         prüft Zeitfenster, Vorab-Info und veraltete Daten
//  Ausgänge (ein Ausgang, mehrere Nachrichten):
//    .../reco/<nutzer>/<route>   Empfehlung + alle Fakten, QoS 1, retained
//    .../alerts/<nutzer>         Meldungen, QoS 1, nicht retained
//
//  Logik (Variante A, "gefühlte Zeit"): Für jede Route werden drei Zeiten in
//  Minuten berechnet; Regen, Wind, Hitze, Höhenmeter, knappe Räder kommen als
//  Aufschläge dazu. Empfohlen wird die schnellste MÖGLICHE Option. Ein Wechsel
//  braucht mind. reco.switchMinGain Minuten Vorteil (sonst springt es hin und her).
//
//  Meldungen aufs Handy gibt es nur im Zeitfenster vor der Abfahrt (reco.windowMin):
//    - Vorab-Info reco.preInfoMin Minuten vor der Abfahrt
//    - bei jedem Wechsel der Empfehlung (nicht, wenn nur Daten ausgefallen sind)
//    - einmalig beim Anlegen einer Route ("Route ist aktiv")
// ============================================================
const cfg = global.get('cfg');
const R = cfg.reco, P = cfg.prefix;
let st = context.get('st');
// Zustand verwerfen, wenn sich das Präfix geändert hat (Context überlebt einen Deploy)
if (!st || st.prefix !== P) {
    st = { prefix: P, profiles: {}, routes: {}, bikes: {}, weather: null, system: {}, last: {}, sent: {} };
    context.set('pending', {});
}
st.routes = st.routes || {};
st.sent = st.sent || {};
const t = msg.topic || '';
const isEmpty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
const allKeys = () => Object.keys(st.profiles);
let affected = [];

if (t.indexOf('/profiles/') >= 0) {
    const key = t.split('/').slice(-2).join('/');
    if (isEmpty) {
        delete st.profiles[key];
        delete st.last[key];
        context.set('st', st);
        node.status({ fill: 'grey', shape: 'dot', text: 'Route entfernt: ' + key });
        return [[{ topic: P + '/reco/' + key, payload: '', qos: 1, retain: true }]];
    }
    st.profiles[key] = msg.payload;
    // retain=false heißt: frisch berechnet (nicht vom Broker nachgeliefert)
    st.fresh = st.fresh || {};
    if (!msg.retain) st.fresh[key] = true;
    affected = [key];
} else if (t.indexOf('/routes/') >= 0) {
    // Nur die Abfahrtszeit interessiert hier; Start/Ziel kommen über das Profil
    const key = t.split('/').slice(-2).join('/');
    if (isEmpty || typeof msg.payload !== 'object') delete st.routes[key];
    else st.routes[key] = { departure: msg.payload.departure || null };
    affected = st.profiles[key] ? [key] : [];
} else if (t.indexOf('/live/bicimad/') >= 0) {
    if (typeof msg.payload !== 'object' || isEmpty) return null;
    const id = t.split('/').pop();
    st.bikes[id] = msg.payload;
    affected = allKeys().filter(k => st.profiles[k].from.id === id || st.profiles[k].to.id === id);
} else if (t.endsWith('/live/weather')) {
    if (typeof msg.payload !== 'object' || isEmpty) return null;
    st.weather = msg.payload;
    affected = allKeys();
} else if (t.indexOf('/system/') >= 0) {
    const name = t.split('/').pop();
    st.system[name] = String(msg.payload);
    st.sysAt = st.sysAt || {};
    st.sysAt[name] = Date.now();     // Zeitpunkt der letzten Statusmeldung
    affected = allKeys();
} else {
    affected = allKeys();   // Takt
}

const round = x => Math.round(x);
// Gründe, die gegen eine Option sprechen (für die Begründung in Meldungen)
const NEG = /keine Räder|nicht verfügbar|veraltet|Regen|Wind|Temperatur|entfernt|derselben|knapp/;
const label = { bike: 'BiciMAD', transit: 'ÖPNV (Schätzung)', walk: 'Zu Fuß' };
const DAYS = ['', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa', 'So'];

// ---------- Uhrzeit in Madrid (Node-RED läuft evtl. in UTC) ----------
function madridNow() {
    const parts = {};
    new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Europe/Madrid', weekday: 'short', year: 'numeric', month: '2-digit',
        day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false
    }).formatToParts(new Date()).forEach(p => { parts[p.type] = p.value; });
    const wd = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 }[parts.weekday];
    return { wd: wd, min: (Number(parts.hour) % 24) * 60 + Number(parts.minute),
        date: parts.year + '-' + parts.month + '-' + parts.day };
}
function daysText(days) {
    const d = (days || []).slice().sort();
    if (d.join() === '1,2,3,4,5') return 'Mo–Fr';
    if (d.length === 7) return 'täglich';
    if (d.join() === '6,7') return 'Sa–So';
    return d.map(x => DAYS[x]).join(', ');
}
// Nächste Abfahrt (heute oder in den nächsten 7 Tagen) und Minuten bis dahin
function schedule(dep) {
    if (!dep || !/^\d{1,2}:\d{2}$/.test(dep.time || '') || !Array.isArray(dep.days) || !dep.days.length) return null;
    const now = madridNow();
    const [h, m] = dep.time.split(':').map(Number);
    const depMin = h * 60 + m;
    for (let off = 0; off <= 7; off++) {
        const wd = ((now.wd - 1 + off) % 7) + 1;
        if (dep.days.indexOf(wd) < 0) continue;
        const diff = off * 1440 + depMin - now.min;
        if (diff < 0) continue;            // heute schon vorbei
        const when = off === 0 ? 'heute' : (off === 1 ? 'morgen' : DAYS[wd]);
        return {
            minutesLeft: diff,
            today: off === 0,
            inWindow: diff <= R.windowMin,
            next: new Date(Math.floor(Date.now() / 60000) * 60000 + diff * 60000).toISOString(),
            nextText: when + ' ' + dep.time,
            occurrence: now.date + '+' + off + '|' + dep.time   // eindeutig je Fahrt
        };
    }
    return null;
}

function compute(p) {
    const now = Date.now();
    const st = context.get('st');
    const notes = [];
    // Ein Collector gilt als lebendig, wenn er "online" meldet ODER nach seiner
    // letzten Statusmeldung noch frische Daten geschickt hat. Das fängt den Fall ab,
    // dass der Broker eine alte Last-Will-Nachricht erst NACH "online" nachliefert.
    const sysAt = st.sysAt || {};
    const alive = (name, ts) => (st.system[name] || '').indexOf('online') === 0 ||
        (ts != null && ts > (sysAt[name] || 0));

    // ---------- Wetter ----------
    const w = st.weather;
    const sysW = st.system.weather || 'unbekannt';
    const weatherOk = !!(w && (now - w.ts) < R.weatherStaleMin * 60000 && (w.demo || alive('weather', w.ts)));
    let rainBike = 0, rainWalk = 0, windBike = 0, tempPen = 0, weatherWhy = null;
    if (weatherOk) {
        if (w.precip >= R.rainHeavy) { rainBike = 2 * R.rainPenaltyBike; rainWalk = 2 * R.rainPenaltyWalk; weatherWhy = 'starker Regen'; }
        else if (w.precip >= R.rainLight) { rainBike = R.rainPenaltyBike; rainWalk = R.rainPenaltyWalk; weatherWhy = 'Regen'; }
        if (w.wind >= R.windStrong) windBike = R.windPenaltyBike;
        if (w.temp < R.coldBelow || w.temp > R.hotAbove) tempPen = R.tempPenalty;
    } else {
        notes.push('ohne Wetterdaten (' + sysW + ')');
    }

    // ---------- BiciMAD ----------
    // Zeit = Fußweg zur Station + Fahrt Station->Station + Ausleihen/Abgeben + Fußweg zum Ziel
    const bike = { mode: 'bike', label: label.bike, min: 0, ok: true, why: [], knapp: false, dataIssue: false };
    const sFrom = st.bikes[p.from.id], sTo = st.bikes[p.to.id];
    const fresh = s => s && typeof s === 'object' && (now - s.ts) < R.staleMin * 60000;
    let bikeDataProblem = false;
    if (p.sameStation || !p.bike) {
        bike.ok = false; bike.why.push('Start und Ziel liegen an derselben Station');
    } else {
        bike.min = p.from.walkMin + p.bike.min + R.dockMin + p.to.walkMin;
        const legs = round(p.from.walkMin + p.to.walkMin);
        if (legs > 0) bike.why.push('inkl. ' + legs + ' min Fußweg zu/von den Stationen');
        if (p.from.distM > R.maxWalkToStationM) { bike.ok = false; bike.why.push('nächste Station am Start ' + p.from.distM + ' m entfernt'); }
        if (p.to.distM > R.maxWalkToStationM) { bike.ok = false; bike.why.push('nächste Station am Ziel ' + p.to.distM + ' m entfernt'); }
        if (!alive('bicimad', sFrom && sFrom.ts)) {
            bike.ok = false; bike.dataIssue = true; bikeDataProblem = true;
            bike.why.push('BiciMAD-Daten nicht verfügbar (' + (st.system.bicimad || 'unbekannt') + ')');
        } else if (!fresh(sFrom) || !fresh(sTo)) {
            bike.ok = false; bike.dataIssue = true; bikeDataProblem = true;
            bike.why.push('Stationsdaten fehlen oder sind veraltet');
        } else {
            // Räder am Start: 0 = nicht möglich, 1-2 = knapp (Aufschlag), ab 3 = sicher
            if (sFrom.bikes < R.bikeMinBikes || !sFrom.renting) {
                bike.ok = false; bike.why.push('keine Räder an ' + p.from.name);
            } else if (sFrom.bikes < R.bikeOkBikes) {
                bike.knapp = true;
                bike.min += R.knappPenalty;
                bike.why.push('knapp: nur ' + sFrom.bikes + (sFrom.bikes === 1 ? ' Rad' : ' Räder') + ' am Start');
            } else {
                bike.why.push(sFrom.bikes + ' Räder am Start');
            }
            // Ziel voll: nur Hinweis, das Rad kann mit Schloss neben der Station abgestellt werden
            if (sTo.docks < R.bikeMinDocks || !sTo.returning) {
                bike.why.push('Ziel voll: Rad mit Schloss neben der Station abstellen');
            } else {
                bike.why.push(sTo.docks + ' freie Plätze am Ziel');
            }
        }
        if (p.bike.ascent != null && p.bike.ascent > 0) {
            bike.min += p.bike.ascent * R.minPerHmUp;
            bike.why.push(round(p.bike.ascent) + ' Hm bergauf (E-Bike)');
        }
        if (p.bike.cyclewayPct != null) {
            bike.min -= R.cyclewayBonusMax * p.bike.cyclewayPct / 100;
            bike.why.push(p.bike.cyclewayPct + ' % Radweg');
        }
        if (rainBike) { bike.min += rainBike; bike.why.push(weatherWhy); }
        if (windBike) { bike.min += windBike; bike.why.push('starker Wind'); }
        if (tempPen) { bike.min += tempPen; bike.why.push('Temperatur ' + round(w.temp) + ' °C'); }
    }

    // ---------- Zu Fuß ----------
    const walk = { mode: 'walk', label: label.walk, min: p.walk.min + rainWalk + tempPen, ok: true, why: [p.walk.km + ' km'] };
    if (rainWalk) walk.why.push(weatherWhy);
    if (tempPen) walk.why.push('Temperatur ' + round(w.temp) + ' °C');

    // ---------- ÖPNV (Schätzung) ----------
    const transit = { mode: 'transit', label: label.transit, min: p.transit.min, ok: true, estimated: true,
        why: ['Schätzung: Fußwege + Warten + Fahrt, kein Fahrplan'] };

    const options = [bike, transit, walk];
    options.forEach(o => { o.min = round(o.min); });
    if (p.source && p.source.indexOf('Schätzung') === 0) notes.push('Streckenprofil geschätzt (ohne ORS)');
    if (p.orsError) notes.push('ORS-Fehler: ' + p.orsError);
    if (bikeDataProblem) notes.push('BiciMAD-Daten fehlen: Empfehlung ohne Fahrrad');

    // Alle Fakten für die Detailansicht im Dashboard (und für andere Clients)
    const facts = {
        fromAddress: p.fromPoint ? p.fromPoint.label : p.from.name,
        toAddress: p.toPoint ? p.toPoint.label : p.to.name,
        fromStation: { id: p.from.id, name: p.from.name, distM: p.from.distM, walkMin: p.from.walkMin,
            capacity: p.from.capacity, bikes: sFrom ? sFrom.bikes : null, docks: sFrom ? sFrom.docks : null, ts: sFrom ? sFrom.ts : null },
        toStation: { id: p.to.id, name: p.to.name, distM: p.to.distM, walkMin: p.to.walkMin,
            capacity: p.to.capacity, bikes: sTo ? sTo.bikes : null, docks: sTo ? sTo.docks : null, ts: sTo ? sTo.ts : null },
        bike: p.bike, walk: p.walk, transit: p.transit, sameStation: !!p.sameStation,
        weather: w ? { temp: w.temp, precip: w.precip, wind: w.wind, ts: w.ts, demo: !!w.demo, ok: weatherOk } : null,
        // angezeigter Status = tatsächlich erkannter Zustand (siehe alive)
        sources: {
            bicimad: alive('bicimad', sFrom && sFrom.ts) ? 'online' : (st.system.bicimad || 'unbekannt'),
            weather: (w && alive('weather', w.ts)) ? 'online' : sysW,
            profile: p.source
        }
    };
    return {
        user: p.user, route: p.route, name: p.name,
        from: facts.fromAddress, to: facts.toAddress,
        options: options, notes: notes, facts: facts,
        dataProblem: bikeDataProblem || !weatherOk,
        updated: new Date().toISOString()
    };
}

// Beste Option mit Mindestvorsprung: Die bisherige Empfehlung bleibt, solange sie
// möglich ist und die schnellste Alternative nicht mind. switchMinGain Minuten besser ist.
// Fehlen gerade Daten (dataProblem), bleibt die bisherige Empfehlung stehen, solange sie
// möglich ist: ein Datenausfall soll die Empfehlung nicht still umwerfen.
function chooseBest(options, prevMode, dataProblem) {
    const ok = options.filter(o => o.ok).sort((a, b) => a.min - b.min);
    if (!ok.length) return options[1];          // ÖPNV ist immer möglich, nur zur Sicherheit
    const fastest = ok[0];
    const prev = ok.find(o => o.mode === prevMode);
    if (prev && dataProblem) return prev;
    if (prev && prev !== fastest && prev.min - fastest.min < R.switchMinGain) return prev;
    return fastest;
}

// Bündeln (Debounce): Kommen mehrere Updates fast gleichzeitig an
// (z. B. Station + Wetter), wird nur EINMAL nach 1 s gerechnet und gesendet.
const pending = context.get('pending') || {};
affected.forEach(k => { pending[k] = true; });
context.set('pending', pending);
context.set('st', st);
if (!context.get('timer')) {
    context.set('timer', true);
    setTimeout(flushPending, 1000);
}
return null;

function flushPending() {
    context.set('timer', false);
    const keys = Object.keys(context.get('pending') || {});
    context.set('pending', {});
    const s = context.get('st');
    const out = [];
    for (const key of keys) {
        const p = s.profiles[key];
        if (!p) continue;
        const prev = s.last[key];
        const reco = compute(p);
        const best = chooseBest(reco.options, prev && prev.best, reco.dataProblem);
        reco.best = best.mode;
        reco.bestLabel = best.label;
        reco.bestMin = best.min;
        reco.summary = best.label + ' · ' + best.min + ' min';
        // Kurze Begründung für Karte und Meldung: die wichtigsten Gründe zuerst
        const reasons = [];
        const bikeOpt = reco.options[0];
        if (best.mode === 'bike') {
            reasons.push(bikeOpt.why.find(x => /am Start/.test(x)) || '');
            reasons.push(...bikeOpt.why.filter(x => /Regen|Wind|Temperatur/.test(x)));
            if (bikeOpt.why.some(x => /Ziel voll/.test(x))) reasons.push('Ziel voll');
        } else {
            reasons.push(...bikeOpt.why.filter(x => NEG.test(x)));
        }
        const others = reco.options.filter(o => o.ok && o !== best).sort((a, b) => a.min - b.min);
        if (others.length) reasons.push(others[0].label.replace(' (Schätzung)', '') + ' ' + others[0].min + ' min' +
            (others[0].min < best.min ? ' (Wechsel erst ab ' + R.switchMinGain + ' min Vorteil)' : ''));
        reco.reason = reasons.filter(Boolean).join(' · ');

        // Abfahrtszeit und Zeitfenster
        const dep = (s.routes[key] || {}).departure || null;
        const sch = schedule(dep);
        reco.departure = dep ? { time: dep.time, days: dep.days, text: daysText(dep.days) + ' ' + dep.time } : null;
        reco.nextDeparture = sch ? sch.next : null;
        reco.nextDepartureText = sch ? sch.nextText : null;
        reco.inWindow = !!(sch && sch.inWindow);
        reco.minutesLeft = sch ? sch.minutesLeft : null;   // Stand beim Senden; Dashboard zählt selbst

        // Signatur ohne Zeitstempel/Minuten: nur senden, wenn sich inhaltlich etwas geändert hat
        const f = reco.facts;
        const sig = JSON.stringify([reco.best, reco.options, reco.notes, reco.reason,
            f.fromStation.bikes, f.fromStation.docks, f.toStation.bikes, f.toStation.docks,
            f.weather && [f.weather.temp, f.weather.precip, f.weather.wind, f.weather.ok], f.sources,
            reco.departure, reco.nextDeparture, reco.inWindow]);
        if (!prev || prev.sig !== sig) {
            out.push({ topic: P + '/reco/' + key, payload: reco, qos: 1, retain: true });
        }

        // ---------- Meldungen ----------
        const isNewRoute = !prev && s.fresh && s.fresh[key];
        if (s.fresh) delete s.fresh[key];
        const preKey = sch ? key + '|' + sch.occurrence : null;
        let text = null;
        if (isNewRoute) {
            text = 'Route "' + reco.name + '" ist aktiv: aktuell ' + reco.summary +
                (reco.departure ? '. Abfahrt ' + reco.departure.text + ', Meldungen ab ' + R.windowMin + ' min vorher.' : '.');
            if (sch && sch.minutesLeft <= R.preInfoMin) {
                text += ' Nächste Abfahrt in ' + sch.minutesLeft + ' min.';
                s.sent[preKey] = Date.now();   // Vorab-Info ist damit erledigt
            }
        } else if (sch && sch.inWindow && sch.minutesLeft <= R.preInfoMin && !s.sent[preKey]) {
            // Vorab-Info: einmal pro Fahrt
            text = 'Route "' + reco.name + '": Abfahrt in ' + sch.minutesLeft + ' min. Heute: ' + reco.summary +
                (reco.reason ? ' (' + reco.reason + ')' : '');
            s.sent[preKey] = Date.now();
        } else if (prev && prev.best !== reco.best && sch && sch.inWindow && !reco.dataProblem) {
            // Wechsel der Empfehlung: nur im Zeitfenster. Während eines Datenausfalls bleibt die
            // Empfehlung stehen (chooseBest); muss sie trotzdem wechseln, weil die bisherige
            // Option ohne Daten unmöglich ist, gibt es dafür keine Meldung.
            const old = reco.options.find(o => o.mode === prev.best);
            let why = old ? old.why.filter(x => NEG.test(x)) : [];
            if (!why.length && reco.best === 'bike') {
                // Zurück zum Fahrrad: sagen, was sich gebessert hat
                const now = reco.options[0].why.filter(x => NEG.test(x));
                why = (prev.bikeNeg || []).filter(x => now.indexOf(x) < 0).map(x =>
                    /Regen/.test(x) ? 'Regen vorbei' : /Wind/.test(x) ? 'Wind hat nachgelassen' :
                    /Temperatur/.test(x) ? 'Temperatur wieder normal' :
                    /Räder|knapp/.test(x) ? (reco.facts.fromStation.bikes + ' Räder am Start') : null)
                    .filter((x, i, a) => x && a.indexOf(x) === i);
            }
            text = 'Route "' + reco.name + '": jetzt ' + reco.summary + ' statt ' + label[prev.best].replace(' (Schätzung)', '') +
                (why.length ? ' (' + why.join(', ') + ')' : '') + '. Abfahrt in ' + sch.minutesLeft + ' min.';
        }
        if (text) out.push({ topic: P + '/alerts/' + p.user, payload: text, qos: 1, retain: false });

        s.last[key] = { sig: sig, best: reco.best, dataProblem: reco.dataProblem,
            // während eines Datenausfalls die letzten bekannten Gründe behalten
            bikeNeg: (reco.dataProblem && prev) ? prev.bikeNeg : reco.options[0].why.filter(x => NEG.test(x)) };
    }
    // Alte Einträge der Vorab-Info aufräumen (älter als 2 Tage)
    for (const k of Object.keys(s.sent)) if (Date.now() - s.sent[k] > 2 * 86400000) delete s.sent[k];
    context.set('st', s);
    node.status({ fill: 'green', shape: 'dot',
        text: Object.keys(s.profiles).length + ' Routen, ' + out.length + ' Nachrichten, ' +
            new Date().toLocaleTimeString('de-DE', { timeZone: 'Europe/Madrid' }) });
    if (out.length) node.send([out]);
}
